  border-color: #ef4444;
  background: #fef2f2;
}
.option-item.correct .option-letter {
  background: #dcfce7;
  border-color: #86efac;
  color: #16a34a;
}
.option-item.incorrect .option-letter {
  background: #fee2e2;
  border-color: #fca5a5;
  color: #dc2626;
}

.form-field.answered {
  pointer-events: none;
}
