AssistantMessageToolRequest(name='create', tool_call_id='tooluse_ca2vp5aBnneWlsPy9I8PMt', arguments={'file_text': 'const questions = [
  {
    id: 'q1',
    text: 'Which of the following are statically typed programming languages?',
    helpText: 'Static typing means variable types are checked at compile time rather than at runtime.',
    options: [
      { letter: 'A', text: 'TypeScript' },
      { letter: 'B', text: 'Python' },
      { letter: 'C', text: 'Java' },
      { letter: 'D', text: 'Go' },
    ],
    correct: ['A', 'C', 'D'],
  },
  {
    id: 'q2',
    text: 'Which languages were primarily designed for systems programming?',
    options: [
      { letter: 'A', text: 'Ruby' },
      { letter: 'B', text: 'Rust' },
      { letter: 'C', text: 'C' },
      { letter: 'D', text: 'JavaScript' },
    ],
    correct: ['B', 'C'],
  },
  {
    id: 'q3',
    text: 'Which of the following languages support first-class functions?',
    options: [
      { letter: 'A', text: 'JavaScript' },
      { letter: 'B', text: 'Haskell' },
      { letter: 'C', text: 'Python' },
      { letter: 'D', text: 'C (pre-C99 standard)' },
    ],
    correct: ['A', 'B', 'C'],
  },
];

function getSelections(questionIndex) {
  const form = document.getElementById('quiz-form');
  const checked = form.querySelectorAll(`input[name="q${questionIndex}"]:checked`);
  return Array.from(checked).map(cb => cb.value);
}

function updateProgress() {
  const answered = questions.filter((_, i) => getSelections(i).length > 0).length;
  const pct = (answered / questions.length) * 100;
  document.getElementById('progress-fill').style.width = `${pct}%`;
  document.getElementById('progress-label').textContent = `${answered} of ${questions.length} answered`;
}

function updateCardState(questionIndex) {
  const card = document.querySelector(`.form-field[data-q="${questionIndex}"]`);
  const hasAny = getSelections(questionIndex).length > 0;
  card.classList.toggle('has-selection', hasAny);
}

function gradeQuiz() {
  let score = 0;

  questions.forEach((q, i) => {
    const card = document.querySelector(`.form-field[data-q="${i}"]`);
    card.classList.add('answered');

    const selected = new Set(getSelections(i));
    const correct = new Set(q.correct);

    const isFullyCorrect =
      selected.size === correct.size &&
      [...selected].every(v => correct.has(v));

    if (isFullyCorrect) score++;

    q.options.forEach(opt => {
      const item = card.querySelector(`.option-item[data-letter="${opt.letter}"]`);
      const isSelected = selected.has(opt.letter);
      const isCorrect = correct.has(opt.letter);

      if (isSelected && isCorrect) item.classList.add('correct');
      else if (isSelected && !isCorrect) item.classList.add('incorrect');
      else if (!isSelected && isCorrect) item.classList.add('correct');
    });
  });

  return score;
}

function showResult(score) {
  const total = questions.length;
  const pct = Math.round((score / total) * 100);
  const panel = document.getElementById('result-panel');
  const emoji = pct === 100 ? '🏆' : pct >= 67 ? '🎉' : pct >= 33 ? '🤔' : '📚';

  document.getElementById('result-emoji').textContent = emoji;
  document.getElementById('result-title').textContent =
    pct === 100 ? 'Perfect score!' : pct >= 67 ? 'Nice work!' : pct >= 33 ? 'Good effort!' : 'Keep learning!';
  document.getElementById('result-score').innerHTML =
    `You got <strong>${score} out of ${total}</strong> questions fully correct (${pct}%).`;

  panel.classList.add('visible');
  panel.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function resetQuiz() {
  const form = document.getElementById('quiz-form');
  form.reset();

  document.querySelectorAll('.form-field').forEach(card => {
    card.classList.remove('answered', 'has-selection');
  });

  document.querySelectorAll('.option-item').forEach(item => {
    item.classList.remove('correct', 'incorrect');
  });

  document.getElementById('result-panel').classList.remove('visible');
  document.getElementById('submit-btn').disabled = false;
  updateProgress();
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('quiz-form');

  form.addEventListener('change', e => {
    if (!e.target.matches('input[type="checkbox"]')) return;
    const qIndex = parseInt(e.target.dataset.q, 10);
    updateCardState(qIndex);
    updateProgress();
  });

  document.getElementById('submit-btn').addEventListener('click', () => {
    const anyAnswered = questions.some((_, i) => getSelections(i).length > 0);
    if (!anyAnswered) {
      alert('Please select at least one answer before submitting.');
      return;
    }
    document.getElementById('submit-btn').disabled = true;
    const score = gradeQuiz();
    showResult(score);
  });

  document.getElementById('retry-btn').addEventListener('click', resetQuiz);

  updateProgress();
});
