  font-weight: 500;
  color: var(--color-text);
  line-height: 1.4;
}

/* Submit */
.quiz-footer {
  margin-top: 8px;
}

.submit-btn {
  width: 100%;
  padding: 15px 24px;
  background: var(--color-primary);
  color: var(--color-primary-fg);
  font-size: 15px;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background .15s, transform .1s, box-shadow .15s;
  box-shadow: 0 1px 2px rgba(99,102,241,.3), 0 4px 12px rgba(99,102,241,.2);
  letter-spacing: .01em;
}

.submit-btn:hover {
  background: var(--color-primary-hover);
  box-shadow: 0 1px 2px rgba(99,102,241,.4), 0 6px 20px rgba(99,102,241,.3);
}

.submit-btn:active {
  transform: translateY(1px);
}

.submit-btn:disabled {
  opacity: .6;
  cursor: not-allowed;
  transform: none;
}

/* Result panel */
.result-panel {
  display: none;
  background: var(--color-surface);
  border: 1px solid var(--color-success-border);
  border-radius: var(--radius-lg);
  padding: 32px 28px;
  margin-top: 16px;
  box-shadow: var(--shadow-card);
  text-align: center;
  animation: slideUp .35s ease;
}

.result-panel.visible {
  display: block;
}

@keyframes slideUp {
  from { opacity: 0; transform: translateY(12px); }
  to   { opacity: 1; transform: translateY(0); }
}

.result-emoji {
  font-size: 48px;
  margin-bottom: 12px;
  line-height: 1;
}

.result-title {
  font-size: 20px;
  font-weight: 700;
  color: var(--color-text);
  margin-bottom: 6px;
}

.result-score {
  font-size: 15px;
  color: var(--color-text-muted);
  margin-bottom: 20px;
}

.result-score strong {
  color: var(--color-primary);
}

.retry-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 20px;
  background: var(--color-check-bg);
  color: var(--color-primary);
  font-size: 14px;
  font-weight: 600;
  border: 1.5px solid var(--color-check-border);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background .15s;
}

.retry-btn:hover {
  background: #e0e7ff;
}

/* Correct / incorrect feedback on options */
.option-item.correct label {
  border-color: #22c55e;
  background: #f0fdf4;
}
.option-item.incorrect label {
  border-color: #ef4444;
  background: #fef2f2;
}
.option-item.correct .option-letter {
  background: #dcfce7;
  border-color: #86efac;
  color: #16a34a;
}
.option-item.incorrect .option-letter {
  background: #fee2e2;
  border-color: #fca5a5;
  color: #dc2626;
}

.form-field.answered {
  pointer-events: none;
}
